  VALUES ('frontend', 'en', 'mid', 'What is the Virtual DOM and how does it improve performance?', 'React keeps a lightweight Virtual DOM tree in memory. On state/prop changes it re-renders the Virtual DOM, computes the diff (reconciliation), and patches only the nodes that actually changed — avoiding costly full DOM repaints.', 1, true)
  RETURNING id
)
