  SELECT id, 2, 'They add runtime null checks automatically' FROM q
UNION ALL
  SELECT id, 3, 'They only work with value types' FROM q;

-- ── go (10 soru) ──
WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'mid', 'How do goroutines differ from OS threads?', 'OS threads start with MBs of stack and have costly OS context switches. Goroutines start with 2KB (growing as needed) and context-switch in user space. The Go scheduler multiplexes goroutines across GOMAXPROCS OS threads. Spawning a goroutine with `go func()` costs almost nothing.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Goroutines and threads are the same thing' FROM q
UNION ALL
  SELECT id, 1, 'Goroutines are lightweight concurrency units managed by the Go runtime (starting at ~2KB stack). Thousands can run concurrently on a small pool of OS threads via M:N scheduling' FROM q
UNION ALL
  SELECT id, 2, 'Goroutines cannot utilise multiple CPU cores' FROM q
UNION ALL
  SELECT id, 3, 'Each goroutine runs on a dedicated CPU core' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'mid', 'What is the difference between a buffered and an unbuffered channel?', 'Unbuffered channels synchronise goroutines — sender and receiver must be ready at the same time. Buffered channels decouple them up to the buffer capacity. Choosing the wrong capacity can cause deadlocks or goroutine leaks.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'They work identically' FROM q
UNION ALL
  SELECT id, 1, 'Unbuffered (`make(chan T)`): sender blocks until receiver is ready — a synchronous rendezvous. Buffered (`make(chan T, n)`): sender blocks only when the buffer is full' FROM q
UNION ALL
  SELECT id, 2, 'Buffered channels are always safer' FROM q
UNION ALL
  SELECT id, 3, 'Unbuffered channels can only be used inside goroutines' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'junior', 'How does `defer` work in Go?', '`defer f.Close()` guarantees cleanup regardless of how the function exits — normal return, early return, or panic. Arguments to deferred calls are evaluated immediately when defer is registered, not when it executes. Named return values can be modified by a deferred function.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'It runs at program startup' FROM q
UNION ALL
  SELECT id, 1, 'A deferred function call is pushed onto a stack and executed when the surrounding function returns (normally or via panic), in LIFO order. Ideal for resource cleanup' FROM q
UNION ALL
  SELECT id, 2, 'Defer only works inside goroutines' FROM q
UNION ALL
  SELECT id, 3, 'You cannot have more than one defer per function' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'junior', 'How are interfaces implemented in Go?', 'Go uses structural typing ("duck typing"): if a type has all the methods an interface requires, it satisfies that interface. No `implements` clause. This loose coupling makes it easy to write against an interface without depending on the concrete type, enabling highly testable code.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'With an explicit `implements` keyword' FROM q
UNION ALL
  SELECT id, 1, 'Implicitly (structural typing): a type satisfies an interface simply by implementing all its methods — no declaration required' FROM q
UNION ALL
  SELECT id, 2, 'Interfaces can only be satisfied with pointer receivers' FROM q
UNION ALL
  SELECT id, 3, 'A type can only satisfy one interface' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'mid', 'What is the idiomatic way to handle errors in Go?', 'Go makes errors explicit values, not exceptions. `f, err := os.Open("file"); if err != nil { return fmt.Errorf("open: %w", err) }` — the `%w` verb wraps the error so callers can unwrap it with `errors.Is` or `errors.As`. This makes error paths clearly visible in code.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Use try/catch/finally' FROM q
UNION ALL
  SELECT id, 1, 'Functions return `error` as the last return value; callers check `if err != nil`. Use `errors.New`, `fmt.Errorf("%w", err)`, and `errors.Is`/`errors.As` for wrapping and inspection' FROM q
UNION ALL
  SELECT id, 2, 'Always use panic for errors' FROM q
UNION ALL
  SELECT id, 3, 'Implementing the error interface is optional' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'mid', 'What is the difference between a slice and an array in Go?', '`[5]int` and `[3]int` are different types. A slice `[]int` is a three-word descriptor pointing into an array. `append()` returns a new slice; if capacity is exceeded, a new backing array is allocated and copied. Slices passed to functions share the backing array — mutations are visible to the caller.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'They are the same' FROM q
UNION ALL
  SELECT id, 1, 'Arrays: fixed size, value type (copied on assignment). Slices: dynamic, a header (pointer + len + cap) into an underlying array; grown with `append()`' FROM q
UNION ALL
  SELECT id, 2, 'Slices are always slower' FROM q
UNION ALL
  SELECT id, 3, 'Arrays can be nil; slices cannot' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'mid', 'What is the difference between a value receiver and a pointer receiver?', '`func (s MyStruct) Method()` — method receives a copy. `func (s *MyStruct) Method()` — method can modify s. Use pointer receivers when the method mutates state or when copying is expensive. A type that implements an interface with pointer receivers can only be stored as `*MyStruct` in that interface.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'They work identically' FROM q
UNION ALL
  SELECT id, 1, 'Value receiver: the method operates on a copy — cannot mutate the original. Pointer receiver: operates on the original struct — can mutate state and avoids copying large structs' FROM q
UNION ALL
  SELECT id, 2, 'Pointer receivers are required for interfaces' FROM q
UNION ALL
  SELECT id, 3, 'Value receivers are always safer' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'senior', 'What does a `select` statement do?', '`select` is the multi-way channel multiplex primitive. If multiple cases are ready, one is chosen randomly. `default` makes select non-blocking (useful for polling). Common pattern: `case <-ctx.Done()` for cancellation propagation.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'It is just another way to write switch' FROM q
UNION ALL
