UNION ALL
  SELECT id, 2, 'It is only used to select goroutines' FROM q
UNION ALL
  SELECT id, 3, 'select only works with buffered channels' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'mid', 'When do you use `sync.WaitGroup` vs `sync.Mutex`?', '`wg.Add(n); go func(){ defer wg.Done() }(); wg.Wait()` — blocks until n goroutines call Done(). `mu.Lock(); sharedCounter++; mu.Unlock()` — prevents a race condition. `sync.RWMutex` allows concurrent reads but exclusive writes for better throughput on read-heavy workloads.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'They solve the same problem' FROM q
UNION ALL
  SELECT id, 1, '`WaitGroup`: wait for a collection of goroutines to finish. `Mutex`: protect shared data from concurrent access (mutual exclusion)' FROM q
UNION ALL
  SELECT id, 2, 'WaitGroup is only for HTTP handlers' FROM q
UNION ALL
  SELECT id, 3, 'Mutex always causes deadlocks' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('go', 'en', 'senior', 'Why is the `context` package important in Go?', '`ctx, cancel := context.WithTimeout(parent, 5*time.Second); defer cancel()` — after 5 s, `ctx.Done()` closes. Database drivers, HTTP clients, and gRPC stubs accept a context and abort when it is cancelled. `context.WithValue` carries trace IDs and auth tokens without polluting function signatures.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Only for storing HTTP request metadata' FROM q
