UNION ALL
  SELECT id, 2, '`context.Background()` should never be used' FROM q
UNION ALL
  SELECT id, 3, 'Context only works with gRPC' FROM q;

-- ── rust (10 soru) ──
WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'en', 'mid', 'What are Rust''s ownership rules?', 'Rust''s three ownership rules: (1) each value has one owner; (2) only one owner at a time; (3) when the owner leaves scope, `drop()` is called automatically. `let s2 = s1` moves a String — s1 is no longer valid. Use `.clone()` for an explicit deep copy.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Multiple variables can own the same value' FROM q
UNION ALL
  SELECT id, 1, 'Each value has exactly one owner. When the owner goes out of scope, the value is dropped. Ownership is transferred (moved) on assignment; the old variable becomes invalid' FROM q
UNION ALL
  SELECT id, 2, 'Memory is managed manually in Rust' FROM q
UNION ALL
  SELECT id, 3, 'Ownership only applies to heap data' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'en', 'senior', 'How does borrowing work with references?', 'The borrow checker enforces this at compile time: many shared readers are fine; exactly one exclusive writer is fine; both simultaneously is not. This eliminates an entire class of bugs — data races, use-after-free, and iterator invalidation — without a garbage collector.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'References cannot be used in Rust' FROM q
UNION ALL
