WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'en', 'mid', 'How does `Result<T, E>` and the `?` operator simplify error handling?', '`let content = fs::read_to_string("f")?;` — if it fails, the function returns `Err(...)` immediately. Chaining: `parse_config()?.validate()?.apply()?` handles each step''s error automatically. `From` trait conversions let you use `?` across different error types. `anyhow` and `thiserror` crates build on this.', 1, true)
