WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('rust', 'en', 'mid', 'What is a trait and how does Rust achieve polymorphism?', '`trait Animal { fn sound(&self) -> &str; }`. `fn make_sound(a: &impl Animal)` is monomorphized — the compiler generates a specialised version per concrete type (zero-cost). `fn make_sound(a: &dyn Animal)` uses a vtable pointer — slower but allows heterogeneous collections like `Vec<Box<dyn Animal>>`.', 1, true)
  RETURNING id
)
