  SELECT id, 0, 'All three are identical' FROM q
UNION ALL
  SELECT id, 1, '`Box<T>`: heap allocation with single ownership. `Rc<T>`: single-thread shared ownership via reference counting. `Arc<T>`: multi-thread safe shared ownership via atomic reference counting' FROM q
UNION ALL
  SELECT id, 2, 'Box is only for recursive types' FROM q
UNION ALL
  SELECT id, 3, 'Arc should always be preferred over Rc' FROM q;

WITH q AS (
