WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'en', 'mid', 'What are the trade-offs between a monorepo and a polyrepo?', 'Google, Meta, and Microsoft use monorepos (Bazel, Nx, Turborepo) for coordinated releases, shared types, and single-PR full-stack changes. Polyrepo suits microservice teams that need strong autonomy boundaries. Nx and Turborepo''s incremental builds mitigate monorepo''s biggest scaling challenge.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Monorepo is always better' FROM q
UNION ALL
  SELECT id, 1, 'Monorepo: shared code, atomic changes, unified CI — but build times and tooling complexity grow. Polyrepo: service independence, isolated CI — but sharing code and coordinating cross-repo changes is harder' FROM q
UNION ALL
  SELECT id, 2, 'Polyrepo is only for large companies' FROM q
UNION ALL
  SELECT id, 3, 'Monorepos are not supported by Git' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'en', 'mid', 'How is Docker multi-stage build used in a full stack project?', '`FROM node:20 AS builder` → `npm ci && npm run build`. `FROM nginx:alpine` → `COPY --from=builder /app/dist /usr/share/nginx/html`. For a Java backend: Maven build stage, then copy only the JAR into a minimal JRE image. This removes compilers and source code from the final image, shrinking attack surface and size.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Multi-stage builds are only for the backend' FROM q
UNION ALL
  SELECT id, 1, 'The frontend build (Node stage) and backend build happen in separate stages; the final image copies only runtime artifacts, keeping development tools out of the production image and minimising its size' FROM q
UNION ALL
  SELECT id, 2, 'Multi-stage builds cannot be used in production' FROM q
UNION ALL
  SELECT id, 3, 'Each stage requires a separate Dockerfile' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('fullstack', 'en', 'senior', 'How is the N+1 problem observed from the frontend and solved in the backend?', 'Symptom: 1 request for posts, then N requests for each post''s comments. Fix: `?include=comments` fetches both in one query. In GraphQL, DataLoader batches the N individual requests into a single `SELECT WHERE id IN (...)`. React Query''s cache prevents re-fetching already-loaded data.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'The N+1 problem only occurs on the frontend' FROM q
UNION ALL
  SELECT id, 1, 'Frontend: the Network tab shows many sequential API requests. Backend: solve with ORM eager loading (JOIN / include), DataLoader for GraphQL batching, or a batch endpoint' FROM q
UNION ALL
  SELECT id, 2, 'Caching always solves the N+1 problem' FROM q
UNION ALL
  SELECT id, 3, 'N+1 only occurs with SQL databases' FROM q;

-- ── system-design (10 soru) ──
WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'junior', 'What is load balancing and what does it provide?', 'Load balancers use algorithms such as Round Robin, Least Connections, IP Hash, and Weighted distribution. L4 balances at the transport layer; L7 can route based on HTTP headers or URL paths. They also perform health checks and SSL termination, removing single points of failure.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'It only monitors network traffic' FROM q
UNION ALL
  SELECT id, 1, 'Distributes incoming requests across multiple servers to provide throughput, high availability, and horizontal scalability' FROM q
UNION ALL
  SELECT id, 2, 'It optimises database queries' FROM q
UNION ALL
  SELECT id, 3, 'It only works with a CDN' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'junior', 'What is a CDN and how does it work?', 'A CDN reduces latency by serving assets from a nearby edge node instead of a distant origin server. It also absorbs DDoS traffic, improves availability, and reduces origin server load. Cloudflare, AWS CloudFront, and Fastly are popular providers.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'It speeds up the database' FROM q
UNION ALL
  SELECT id, 1, 'A network of geographically distributed edge servers that cache static assets (images, JS, CSS) and serve them from the location closest to the user' FROM q
UNION ALL
  SELECT id, 2, 'Only used for video streaming' FROM q
UNION ALL
  SELECT id, 3, 'It provides server security' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'junior', 'What is the difference between horizontal and vertical scaling?', 'Vertical scaling is simple but has a hard ceiling and introduces a single point of failure. Horizontal scaling is theoretically unlimited and enables high availability, but requires stateless services, a load balancer, and distributed session/cache management. Modern cloud architectures default to horizontal.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'They are the same thing' FROM q
UNION ALL
  SELECT id, 1, 'Vertical (scale up): add more CPU/RAM to the existing server. Horizontal (scale out): add more servers' FROM q
UNION ALL
  SELECT id, 2, 'Horizontal scaling is always more expensive' FROM q
UNION ALL
  SELECT id, 3, 'Vertical scaling has no limits' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'senior', 'What are the main cache invalidation strategies?', '"Cache invalidation and naming things are the two hardest problems in computer science." — Phil Karlton. TTL is simple but risks stale data. Write-through keeps cache consistent but adds write latency. Event-driven (publishing an invalidation message) is most accurate but complex. Choose based on tolerance for stale data vs. consistency requirements.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Cache is never invalidated' FROM q
UNION ALL
  SELECT id, 1, 'TTL (expire after a duration), write-through (update cache on write), write-invalidate (delete cache entry on write), and event-driven invalidation' FROM q
UNION ALL
  SELECT id, 2, 'Only manual cache clearing exists' FROM q
UNION ALL
  SELECT id, 3, 'Cache is automatically cleared after each request' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'mid', 'What is an API Gateway?', 'An API Gateway (Kong, AWS API GW, Nginx) consolidates cross-cutting concerns that would otherwise be duplicated in every microservice. Clients call one endpoint; the gateway routes to the appropriate service. It enables canary deployments, A/B testing, and request/response transformation.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'A service used only for authentication' FROM q
UNION ALL
  SELECT id, 1, 'A single entry point for all client requests to microservices; handles routing, authentication, rate limiting, logging, and SSL termination centrally' FROM q
UNION ALL
  SELECT id, 2, 'A type of database' FROM q
UNION ALL
  SELECT id, 3, 'A frontend framework' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'senior', 'What is the Circuit Breaker pattern?', 'States: Closed (normal operation), Open (failure threshold exceeded — requests fail immediately), Half-Open (a probe request tests recovery). If the probe succeeds, the circuit closes again. This prevents a slow or dead service from exhausting threads and bringing down the whole system.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'An algorithm for managing electrical circuits' FROM q
UNION ALL
  SELECT id, 1, 'A pattern that stops sending requests to a failing downstream service, preventing cascade failures and allowing the system to self-heal' FROM q
UNION ALL
  SELECT id, 2, 'Only used for database connections' FROM q
UNION ALL
  SELECT id, 3, 'A load balancing algorithm' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'senior', 'What is consistent hashing?', 'Standard hashing: adding one node remaps ~n/N keys. Consistent hashing places nodes and keys on a virtual ring; adding/removing a node only affects the adjacent keys. Used in Cassandra, DynamoDB, and Memcached. Virtual nodes (vnodes) further improve load distribution.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'An improved version of a standard hash function' FROM q
UNION ALL
  SELECT id, 1, 'A hashing technique for distributed systems that minimises the number of keys that must be remapped when nodes are added or removed' FROM q
UNION ALL
  SELECT id, 2, 'An encryption algorithm' FROM q
UNION ALL
  SELECT id, 3, 'A database indexing method' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'senior', 'What is Event Sourcing?', 'Event Sourcing stores "what happened" rather than "what is". The full audit trail is inherent. You can replay events to rebuild state at any point in time, enabling temporal queries and debugging. Natural fit for CQRS, domain-driven design, and financial systems.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'A technique for managing event listeners' FROM q
UNION ALL
  SELECT id, 1, 'Instead of storing current state, every state change is stored as an immutable event. The current state is derived by replaying the event log' FROM q
UNION ALL
  SELECT id, 2, 'A frontend event management pattern' FROM q
UNION ALL
  SELECT id, 3, 'A log aggregation method for microservices' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'senior', 'What is CQRS (Command Query Responsibility Segregation)?', 'The write side uses a normalised model optimised for consistency; the read side uses a denormalised model (or materialized view) optimised for queries. They can be scaled independently. Useful for complex domains, but overkill for simple CRUD. Often paired with Event Sourcing.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'A way to separate CSS from JavaScript' FROM q
UNION ALL
  SELECT id, 1, 'A pattern that uses separate models (or services) for write operations (Commands) and read operations (Queries), enabling independent optimisation and scaling of each' FROM q
UNION ALL
  SELECT id, 2, 'Only applicable to microservices' FROM q
UNION ALL
  SELECT id, 3, 'A database backup strategy' FROM q;

WITH q AS (
  INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active)
  VALUES ('system-design', 'en', 'mid', 'What algorithms are used for rate limiting?', 'Token Bucket: allows controlled bursts, refills at a fixed rate. Leaky Bucket: processes at a constant rate, smoothing bursts. Fixed Window: simple but vulnerable to edge-of-window spikes. Sliding Window: more fair, higher memory. Stripe and Cloudflare use sliding window variants. Redis is a common backing store for distributed counters.', 1, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_index, option_text)
  SELECT id, 0, 'Only a simple counter algorithm' FROM q
UNION ALL
  SELECT id, 1, 'Token Bucket, Leaky Bucket, Fixed Window Counter, Sliding Window Log/Counter' FROM q
UNION ALL
  SELECT id, 2, 'It can only be implemented with Redis' FROM q
UNION ALL
  SELECT id, 3, 'Rate limiting does not require an algorithm' FROM q;
